<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('marketing');$pageTitle='Campaign List';$activeMenu='campaign-list';$rows=db()->query("SELECT c.*,d.name department,CONCAT(u.first_name,' ',u.last_name) creator,CASE WHEN c.actual_spending>0 THEN ((c.generated_sales-c.actual_spending)/c.actual_spending)*100 ELSE 0 END roi FROM campaigns c JOIN departments d ON d.id=c.department_id JOIN users u ON u.id=c.created_by ORDER BY c.start_date DESC,c.id DESC")->fetchAll();$campaignBudget=array_sum(array_column($rows,'budget'));$campaignSpend=array_sum(array_column($rows,'actual_spending'));$campaignSales=array_sum(array_column($rows,'generated_sales'));$portfolioRoi=$campaignSpend>0?(($campaignSales-$campaignSpend)/$campaignSpend*100):0;$activeCampaigns=count(array_filter($rows,fn($r)=>$r['status']==='Active'));require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Marketing Campaigns</h1><p>Plan campaigns, monitor spend, generated sales and ROI.</p></div><a class="btn btn-primary" href="<?=e(url('marketing/create.php'))?>"><i class="fa-solid fa-plus me-2"></i>Add Campaign</a></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="kpi-card"><div class="kpi-label">Campaign Budget</div><div class="kpi-value"><?=money($campaignBudget)?></div><div class="kpi-meta">Across <?=count($rows)?> campaigns</div></div></div><div class="col-md-3"><div class="kpi-card"><div class="kpi-label">Actual Spending</div><div class="kpi-value"><?=money($campaignSpend)?></div><div class="kpi-meta"><?=$activeCampaigns?> active campaign(s)</div></div></div><div class="col-md-3"><div class="kpi-card"><div class="kpi-label">Generated Sales</div><div class="kpi-value"><?=money($campaignSales)?></div><div class="kpi-meta">Campaign-attributed sales</div></div></div><div class="col-md-3"><div class="kpi-card"><div class="kpi-label">Portfolio ROI</div><div class="kpi-value <?=$portfolioRoi>=0?'roi-positive':'roi-negative'?>"><?=number_format($portfolioRoi,1)?>%</div><div class="kpi-meta">Return on actual campaign spend</div></div></div></div><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Campaign</th><th>Type</th><th>Department</th><th>Period</th><th class="text-end">Budget</th><th class="text-end">Spending</th><th class="text-end">Generated Sales</th><th>ROI</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold text-primary"><?=e($r['campaign_name'])?></td><td><?=e($r['campaign_type'])?></td><td><?=e($r['department'])?></td><td><?=e(date('M d',strtotime($r['start_date'])).' – '.date('M d, Y',strtotime($r['end_date'])))?></td><td class="text-end"><?=money($r['budget'])?></td><td class="text-end"><?=money($r['actual_spending'])?></td><td class="text-end"><?=money($r['generated_sales'])?></td><td class="<?=$r['roi']>=0?'roi-positive':'roi-negative'?>"><?=number_format((float)$r['roi'],1)?>%</td><td><?=status_badge($r['status'])?></td><td><div class="table-actions"><a class="btn btn-light border" href="<?=e(url('marketing/edit.php?id='.$r['id']))?>"><i class="fa-solid fa-pen"></i></a><a class="btn btn-light border" href="<?=e(url('marketing/expenses.php?campaign_id='.$r['id']))?>"><i class="fa-solid fa-receipt"></i></a><?php if(has_role(['Administrator','Marketing Manager'])):?><a data-confirm="Delete this campaign and its expense entries?" class="btn btn-light border text-danger" href="<?=e(url('marketing/delete.php?id='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-trash"></i></a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
